describe('Cancel In-Progress Upload', () => {
  beforeEach(() => {
    cy.visit('/upload');
    cy.get('[data-testid="upload-input"]').should('be.visible');
  });

  it('should cancel an in-progress upload successfully', () => {
    // Create a large file to ensure upload is in progress
    const largeFile = new File(['x'.repeat(5000000)], 'large-file.txt', { type: 'text/plain' });

    // Trigger file input
    cy.get('[data-testid="upload-input"]').selectFile({
      contents: Cypress.Buffer.from('x'.repeat(5000000)),
      fileName: 'large-file.txt',
      mimeType: 'text/plain'
    });

    // Verify upload has started
    cy.get('[data-testid="upload-progress"]').should('be.visible');
    cy.get('[data-testid="upload-progress-bar"]').should('have.attr', 'aria-valuenow').and('be.greaterThan', 0);

    // Click cancel button
    cy.get('[data-testid="cancel-upload-btn"]').should('be.enabled').click();

    // Verify upload was cancelled
    cy.get('[data-testid="upload-progress"]').should('not.exist');
    cy.get('[data-testid="upload-error-message"]').should('contain', 'Upload cancelled');
    cy.get('[data-testid="cancel-upload-btn"]').should('be.disabled');
  });

  it('should handle cancel button click when upload is nearly complete', () => {
    // Create a smaller file that uploads quickly
    cy.get('[data-testid="upload-input"]').selectFile({
      contents: Cypress.Buffer.from('x'.repeat(100000)),
      fileName: 'small-file.txt',
      mimeType: 'text/plain'
    });

    // Wait a moment for upload to start
    cy.get('[data-testid="upload-progress"]').should('be.visible');

    // Attempt to cancel
    cy.get('[data-testid="cancel-upload-btn"]').click();

    // Verify either upload completed or was cancelled
    cy.get('[data-testid="upload-status"]').should('satisfy', ($el) => {
      const text = $el.text();
      return text.includes('cancelled') || text.includes('completed');
    });
  });

  it('should disable cancel button when no upload is in progress', () => {
    // Verify cancel button is disabled initially
    cy.get('[data-testid="cancel-upload-btn"]').should('be.disabled');

    // Attempt to click disabled button
    cy.get('[data-testid="cancel-upload-btn"]').should('have.attr', 'disabled');
  });

  it('should restore UI to initial state after cancellation', () => {
    // Start upload
    cy.get('[data-testid="upload-input"]').selectFile({
      contents: Cypress.Buffer.from('x'.repeat(5000000)),
      fileName: 'test-file.txt',
      mimeType: 'text/plain'
    });

    cy.get('[data-testid="upload-progress"]').should('be.visible');

    // Cancel upload
    cy.get('[data-testid="cancel-upload-btn"]').click();

    // Verify UI returns to initial state
    cy.get('[data-testid="upload-progress"]').should('not.exist');
    cy.get('[data-testid="upload-input"]').should('be.visible');
    cy.get('[data-testid="cancel-upload-btn"]').should('be.disabled');
    cy.get('[data-testid="upload-error-message"]').should('be.visible');
  });
});
